// context-packet.js — bounded evidence packer.
//
// Deterministic UTF-8 byte-budget packer for context sections. Node.js
// builtins only. Not a tokenizer and not a claim about optimal model context.

import {readFileSync} from 'node:fs';

function isPlainObject(v){
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function frameFor(id,text){
  // Exact serialized frame: '### ' + JSON.stringify(id) + '\n' + text + '\n'
  return '### ' + JSON.stringify(id) + '\n' + text + '\n';
}

export function packContext(sections,maxBytes){
  // ---- validate the entire input before packing --------------------------
  if (typeof maxBytes !== 'number' || !Number.isSafeInteger(maxBytes) || maxBytes < 0){
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)){
    throw new Error('sections must be an array');
  }
  const n = sections.length;
  const entries = new Array(n);
  const seenIds = new Set();
  for (let i = 0; i < n; i++){
    const s = sections[i];
    if (s === undefined){
      throw new Error(`sections[${i}] is missing; array slots must not be omitted`);
    }
    if (!isPlainObject(s)){
      throw new Error(`sections[${i}] must be a non-null, non-array object`);
    }
    if (typeof s.id !== 'string' || s.id.length === 0){
      throw new Error(`sections[${i}].id must be a nonempty string`);
    }
    if (typeof s.text !== 'string'){
      throw new Error(`sections[${i}].text must be a string`);
    }
    if (typeof s.priority !== 'number' || !Number.isSafeInteger(s.priority) || s.priority < 0){
      throw new Error(`sections[${i}].priority must be a nonnegative safe integer`);
    }
    if (typeof s.required !== 'boolean'){
      throw new Error(`sections[${i}].required must be a boolean`);
    }
    if (seenIds.has(s.id)){
      throw new Error(`duplicate section id: ${JSON.stringify(s.id)}`);
    }
    seenIds.add(s.id);
    const frame = frameFor(s.id,s.text);
    entries[i] = {
      id: s.id,
      frame,
      cost: Buffer.byteLength(frame,'utf8'),
      priority: s.priority,
      required: s.required,
      index: i,
    };
  }

  // ---- select ------------------------------------------------------------
  let remaining = maxBytes;
  let bytes = 0;
  const included = [];

  // 1. All required sections first, in original input order. Their priority
  //    is ignored. If they do not all fit, throw rather than return a
  //    partial required set.
  for (let i = 0; i < n; i++){
    const e = entries[i];
    if (!e.required) continue;
    if (e.cost > remaining){
      throw new Error('required sections exceed the maxBytes budget');
    }
    remaining -= e.cost;
    bytes += e.cost;
    included.push(e);
  }

  // 2. Optional sections by descending priority, ties by original input
  //    order. Include when the whole frame fits; otherwise skip and continue.
  const includedAt = new Set(included.map((e) => e.index));
  const optional = entries.filter((e) => !e.required);
  optional.sort((a,b) => a.priority === b.priority ? a.index - b.index : b.priority - a.priority);
  for (const e of optional){
    if (e.cost <= remaining){
      remaining -= e.cost;
      bytes += e.cost;
      included.push(e);
      includedAt.add(e.index);
    }
  }

  // ---- report --------------------------------------------------------------
  // 3. Output in inclusion order; omitted optional IDs in original input order.
  const text = included.map((e) => e.frame).join('');
  const omitted = [];
  for (let i = 0; i < n; i++){
    const e = entries[i];
    if (!e.required && !includedAt.has(i)) omitted.push(e.id);
  }

  return {
    text,
    bytes,
    included: included.map((e) => e.id),
    omitted,
  };
}

// ---- CLI --------------------------------------------------------------------

function fail(message){
  process.stderr.write(message + '\n');
  process.exitCode = 2;
}

function cliMain(){
  const args = process.argv.slice(2);
  if (args.length !== 1){
    fail('usage: node context-packet.js INPUT_JSON_FILE');
    return;
  }
  let raw;
  try {
    raw = readFileSync(args[0],'utf8');
  } catch (err) {
    fail(`cannot read ${args[0]}: ${err.message}`);
    return;
  }
  let root;
  try {
    root = JSON.parse(raw);
  } catch (err) {
    fail(`invalid JSON: ${err.message}`);
    return;
  }
  if (!isPlainObject(root)){
    fail('input JSON must be an object of the form {sections, maxBytes}');
    return;
  }
  try {
    const result = packContext(root.sections,root.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (err) {
    fail(err.message);
  }
}

function isMainModule(){
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return import.meta.url === new URL(entry,'file:///').href;
  } catch {
    return false;
  }
}

if (isMainModule()){
  cliMain();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,writeFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {packContext} from '../context-packet.js';

const MODULE = fileURLToPath(new URL('../context-packet.js',import.meta.url));
const section=(id,text,priority=0,required=false)=>({id,text,priority,required});

test('priority tie-break is original input order',()=>{
  const r = packContext([
    section('low','a',1),
    section('mid','b',5),
    section('hi','c',5),
  ],100);
  assert.deepEqual(r.included,['hi','mid','low']);
  assert.equal(r.bytes, Buffer.byteLength('### "c"\nc\n### "b"\nb\n### "a"\na\n','utf8'));
});

test('frames are indivisible: skip instead of truncate; continue after a skip',()=>{
  const costA = Buffer.byteLength('### "a"\na\n','utf8');
  const r = packContext([
    section('big','x'.repeat(50),10),
    section('a','a',5),
    section('b','b',1),
  ], costA + Buffer.byteLength('### "b"\nb\n','utf8'));
  assert.deepEqual(r.included,['a','b']);
  assert.deepEqual(r.omitted,['big']);
  assert.equal(r.bytes, costA + Buffer.byteLength('### "b"\nb\n','utf8'));
});

test('omitted optional IDs are reported in input order, not priority order',()=>{
  const r = packContext([
    section('p1','x',1),
    section('p3','x',3),
    section('p2','x',2),
  ], 20);
  assert.deepEqual(r.omitted,['p1','p2']); // priority desc would be p1,p3,p2 -> p1,p2 here because p3 also omitted? no: p3 included first? see below
});

test('unicode, spaces, newlines, NUL and __proto__ ids are valid and unique',()=>{
  const ids = ['__proto__','a b','c\n\t\u0000','ünïcode','A','a'];
  const sections = ids.map((id,i)=>section(id,'t',i,true));
  const r = packContext(sections, 10000);
  assert.deepEqual(r.included, ids);
  assert.equal(r.omitted.length,0);
  assert.ok(r.text.includes('### "__proto__"'));
  // 'A' vs 'a' are distinct exact strings
  assert.ok(r.text.includes('### "A"'));
  assert.ok(r.text.includes('### "a"'));
  // NUL preserved verbatim in the id frame
  assert.ok(r.text.includes('### "c\\n\\t\\u0000"'));
});

test('unknown object fields are ignored; exact fits allowed',()=>{
  const r = packContext([section('x','y',0,false,{note:'ignore me','__proto__':1})],
    Buffer.byteLength('### "x"\ny\n','utf8'));
  assert.deepEqual(r,{text:'### "x"\ny\n',bytes:r.bytes,included:['x'],omitted:[]});
});

test('input is never mutated (no prototype-pollution, no added props)',()=>{
  const obj = {id:'a',text:'a',priority:0,required:false};
  const before = JSON.stringify(obj);
  packContext([obj,section('b','b',0,true)],100);
  assert.equal(JSON.stringify(obj),before);
  assert.equal(Object.keys(obj).length,4);
  assert.equal(obj.note,undefined);
});

test('validation throws even when budget is zero or section would be omitted',()=>{
  assert.throws(()=>packContext([section('ok','x'),section('', 'x')],0),Error);
  assert.throws(()=>packContext([section('ok','x',0),section('bad',123)],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),section('bad','y',-1)],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),section('bad','y',0,null)],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),section('bad','y','0')],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),section('bad','y',Number.MAX_SAFE_INTEGER+2)],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),section('bad','y',NaN)],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),section('bad','y',1.5)],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),section('bad',true)],1000),Error);
  assert.throws(()=>packContext([section(1,'x')],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),section('bad','y',0,true,undefined),null],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),[1,2]],1000),Error);
  assert.throws(()=>packContext([section('ok','x'),'str'],1000),Error);
  assert.throws(()=>packContext(new Array(2),1000),Error); // holes
  assert.throws(()=>packContext('not-array',1000),Error);
  assert.throws(()=>packContext(null,1000),Error);
  assert.throws(()=>packContext([section('ok','x')],-1),Error);
  assert.throws(()=>packContext([section('ok','x')],1.5),Error);
  assert.throws(()=>packContext([section('ok','x')],NaN),Error);
  assert.throws(()=>packContext([section('ok','x')],Infinity),Error);
  assert.throws(()=>packContext([section('ok','x')],'100'),Error);
  assert.throws(()=>packContext([section('ok','x')],undefined),Error);
  assert.throws(()=>packContext([section('ok','x')],null),Error);
  assert.throws(()=>packContext(undefined,100),Error);
});

test('required overflow throws even when optional sections would not fit anyway',()=>{
  assert.throws(()=>packContext(
    [section('opt','x'.repeat(100),99),section('req','x'.repeat(100),0,true)],
    10),Error);
});

test('maxBytes zero with valid empty and with empty optional fits',()=>{
  assert.deepEqual(packContext([],0),{text:'',bytes:0,included:[],omitted:[]});
  assert.deepEqual(packContext([section('o','x',3)],0),
    {text:'',bytes:0,included:[],omitted:['o']});
});

test('CLI end-to-end in tmpdir fixtures',()=>{
  const dir = mkdtempSync(join(tmpdir(),'context-packet-test-'));
  const run=(fileOrArgs,extraArgs=[])=>{
    const args = fileOrArgs===null ? [] : [fileOrArgs,...extraArgs];
    return spawnSync(process.execPath,[MODULE,...args],{encoding:'utf8'});
  };
  try {
    // success: exact bytes + single newline + no stderr + exit 0
    const okFile = join(dir,'ok.json');
    writeFileSync(okFile,JSON.stringify({
      extra:'ignored',
      maxBytes:100,
      sections:[section('extra','x',50),section('rule','Do it.',0,true)],
    }));
    const ok = run(okFile);
    assert.equal(ok.status,0);
    assert.equal(ok.stderr,'');
    const expected = JSON.stringify({
      text:'### "rule"\nDo it.\n### "extra"\nx\n',bytes:32,included:['rule','extra'],omitted:[]});
    assert.equal(ok.stdout, expected + '\n');

    // success: empty input, any budget
    const emptyFile = join(dir,'empty.json');
    writeFileSync(emptyFile,JSON.stringify({sections:[],maxBytes:0}));
    const e = run(emptyFile);
    assert.equal(e.status,0);
    assert.equal(e.stdout, JSON.stringify({text:'',bytes:0,included:[],omitted:[]}) + '\n');

    // invalid: missing file
    const missing = run(join(dir,'nope.json'));
    assert.equal(missing.status,2);
    assert.equal(missing.stdout,'');
    assert.ok(missing.stderr.length > 0);

    // invalid: bad JSON
    const badJson = join(dir,'bad.json');
    writeFileSync(badJson,'{not json');
    const bj = run(badJson);
    assert.equal(bj.status,2);
    assert.equal(bj.stdout,'');
    assert.ok(bj.stderr.length > 0);

    // invalid: non-object JSON
    const badRoot = join(dir,'root.json');
    writeFileSync(badRoot,'[1,2,3]');
    const br = run(badRoot);
    assert.equal(br.status,2);
    assert.equal(br.stdout,'');
    assert.ok(br.stderr.length > 0);

    // invalid: duplicate id in file
    const dup = join(dir,'dup.json');
    writeFileSync(dup,JSON.stringify({sections:[section('a','x'),section('a','y')],maxBytes:100}));
    const d = run(dup);
    assert.equal(d.status,2);
    assert.equal(d.stdout,'');
    assert.ok(d.stderr.length > 0);

    // invalid: required overflow
    const over = join(dir,'over.json');
    writeFileSync(over,JSON.stringify({sections:[section('r','x',0,true)],maxBytes:0}));
    const o = run(over);
    assert.equal(o.status,2);
    assert.equal(o.stdout,'');
    assert.ok(o.stderr.length > 0);

    // invalid: missing maxBytes
    const noMax = join(dir,'nomax.json');
    writeFileSync(noMax,JSON.stringify({sections:[]}));
    const nm = run(noMax);
    assert.equal(nm.status,2);
    assert.equal(nm.stdout,'');
    assert.ok(nm.stderr.length > 0);

    // arg count: zero and two args
    assert.equal(run(null).status,2);
    assert.equal(run(null,[]) && 'x','x'); // keep shape
    const two = spawnSync(process.execPath,[MODULE,okFile,okFile],{encoding:'utf8'});
    assert.equal(two.status,2);
    assert.equal(two.stdout,'');
    assert.ok(two.stderr.length > 0);

    // importing does not run the CLI: a file with no args imported must not fail the import
    const importResult = spawnSync(process.execPath,['--input-type=module','-e',
      `import {packContext} from ${JSON.stringify(MODULE)};
       if (packContext([],0).bytes !== 0) process.exit(3);`],
      {encoding:'utf8'});
    assert.equal(importResult.stdout,'');
    assert.equal(importResult.stderr,'');
    assert.equal(importResult.status,0);
  } finally {
    rmSync(dir,{recursive:true,force:true});
  }
  assert.ok(!require('node:fs').existsSync(dir));
});

